const Imap = require('imap');
const { simpleParser } = require('mailparser');
const iconv = require('iconv-lite');

function detectAndFixEncoding(buffer) {
    // Проверяем наличие типичных крякозябр
    const bufferStr = buffer.toString('binary');

    // Паттерны крякозябр для разных кодировок
    const patterns = {
        'win1251': /ïðèâåò|äîáðûé|ñïàñèáî|êàê|÷òî/,
        'koi8-r': /╨┐╤Ç╨╕╨▓╨╡╤é|╨┤╨╛╨▒╤Ç╤ï╨╣|╤ü╨┐╨░╤ü╨╕╨▒╨╛/,
        'iso-8859-5': /ðòèâåò|äîáðûé|ñïàñèáî/,
        'cp866': /ðƒð©ð▓ðÁÐé|ð┤ð¥ð▒ÐÇÐïð╣|Ðüð┐ð░Ðüð©ð▒ð¥/
    };

    for (const [encoding, pattern] of Object.entries(patterns)) {
        if (pattern.test(bufferStr)) {
            try {
                return iconv.decode(buffer, encoding);
            } catch (e) {
                continue;
            }
        }
    }

    return null;
}

function fixTextEncoding(text) {
    if (!text) return text;

    // Список распространенных замен крякозябр
    const replacements = [
        // Windows-1251 кракозябры
        { pattern: /ïðèâåò/g, replacement: 'привет' },
        { pattern: /äîáðûé/g, replacement: 'добрый' },
        { pattern: /ñïàñèáî/g, replacement: 'спасибо' },
        { pattern: /êàê/g, replacement: 'как' },
        { pattern: /÷òî/g, replacement: 'что' },
        { pattern: /äåíü/g, replacement: 'день' },
        { pattern: /óâàæàåìûé/g, replacement: 'уважаемый' },
        { pattern: /êëèåíò/g, replacement: 'клиент' },
        { pattern: /ïèñüìî/g, replacement: 'письмо' },

        // KOI8-R кракозябры
        { pattern: /╨┐╤Ç╨╕╨▓╨╡╤é/g, replacement: 'привет' },
        { pattern: /╨┤╨╛╨▒╤Ç╤ï╨╣/g, replacement: 'добрый' },
        { pattern: /╤ü╨┐╨░╤ü╨╕╨▒╨╛/g, replacement: 'спасибо' },

        // Другие распространенные искажения
        { pattern: /â/g, replacement: '–' }, // тире
        { pattern: /â/g, replacement: '—' }, // длинное тире
        { pattern: /â/g, replacement: '’' }, // апостроф
        { pattern: /â/g, replacement: '“' }, // открывающая кавычка
        { pattern: /â/g, replacement: '”' }, // закрывающая кавычка
        { pattern: /Ã©/g, replacement: 'é' },
        { pattern: /Ã¨/g, replacement: 'è' },
        { pattern: /Ãª/g, replacement: 'ê' },
        { pattern: /Ã§/g, replacement: 'ç' },
        { pattern: /Ã /g, replacement: 'à' },
        { pattern: /Ã¡/g, replacement: 'á' },
        { pattern: /Ã¢/g, replacement: 'â' },
        { pattern: /Ã£/g, replacement: 'ã' },
        { pattern: /Ã¤/g, replacement: 'ä' },
    ];

    let fixedText = text;
    for (const { pattern, replacement } of replacements) {
        fixedText = fixedText.replace(pattern, replacement);
    }

    return fixedText;
}

function decodeEmailContent(buffer) {
    const encodings = ['utf-8', 'windows-1251', 'koi8-r', 'iso-8859-5', 'cp866', 'maccyrillic'];

    // Пробуем разные кодировки
    for (const encoding of encodings) {
        try {
            const decoded = iconv.decode(buffer, encoding);
            // Проверяем, нет ли явных крякозябр
            if (!decoded.includes('пї') && !decoded.includes('�') && 
                !decoded.includes('ïðèâåò') && !decoded.includes('╨┐╤Ç╨╕╨▓╨╡╤é')) {
                return decoded;
            }
        } catch (e) {
            continue;
        }
    }

    // Если ни одна кодировка не подошла, возвращаем как есть
    return iconv.decode(buffer, 'utf-8');
}

async function fetchUnread(imap_host, imap_port, imap_user, imap_pass) {
    return new Promise((resolve, reject) => {
        const results = [];
        const imap = new Imap({
            user: imap_user,
            password: imap_pass,
            host: imap_host,
            port: parseInt(imap_port),
            tls: true,
            tlsOptions: { rejectUnauthorized: false }
        });

        imap.once('ready', function () {
            imap.openBox('Рассылки|К обработке с ИИ', false, function (err, box) {
                if (err) return reject(err);

                imap.search(['ALL'], function (err, uids) {
                    if (err) return reject(err);
                    if (!uids.length) {
                        imap.end();
                        return resolve([]);
                    }

                    // Ограничиваем количество писем до 100
                    // Берем последние 100 писем (самые новые)
                    const uidsToFetch = uids.slice(-100);
                    console.log(`Найдено всего писем: ${uids.length}, загружаем последние ${uidsToFetch.length}`);

                    const f = imap.fetch(uidsToFetch, { 
                        bodies: '',
                        struct: true 
                    });
                    let idCounter = 1;
                    let processed = 0;
                    const total = uidsToFetch.length;

                    f.on('message', function (msg) {
                        let buffers = [];
                        let uid;

                        msg.on('attributes', attrs => {
                            uid = attrs.uid;
                        });

                        msg.on('body', function (stream, info) {
                            const chunks = [];
                            stream.on('data', chunk => chunks.push(chunk));
                            stream.on('end', () => {
                                buffers.push(Buffer.concat(chunks));
                            });
                        });

                        msg.once('end', async function () {
                            try {
                                processed++;
                                const buffer = Buffer.concat(buffers);

                                // Декодируем с правильной кодировкой
                                const decodedBuffer = decodeEmailContent(buffer);

                                let parsed;
                                try {
                                    parsed = await simpleParser(decodedBuffer);
                                } catch (parseErr) {
                                    // Если не удалось распарсить, пробуем другие подходы
                                    console.log(`Ошибка парсинга, пробую альтернативные методы...`);

                                    // Метод 1: Пробуем распарсить оригинальный buffer
                                    try {
                                        parsed = await simpleParser(buffer);
                                    } catch (e1) {
                                        // Метод 2: Пробуем автоматическое определение кодировки
                                        const fixedEncoding = detectAndFixEncoding(buffer);
                                        if (fixedEncoding) {
                                            parsed = await simpleParser(fixedEncoding);
                                        } else {
                                            // Метод 3: Используем последнюю попытку
                                            parsed = {
                                                from: { value: [{ address: '' }], text: '' },
                                                to: { value: [{ address: '' }], text: '' },
                                                subject: '',
                                                text: '',
                                                html: '',
                                                messageId: '',
                                                date: new Date(),
                                                references: [],
                                                inReplyTo: ''
                                            };
                                        }
                                    }
                                }

                                // Исправляем крякозябры в текстах
                                const fixedSubject = fixTextEncoding(parsed.subject || '');
                                const fixedText = fixTextEncoding(parsed.text || '');
                                // const fixedHtml = fixTextEncoding(parsed.html || '');

                                // Извлекаем email адреса из заголовков
                                let senderEmail = '';
                                let recipientEmail = '';

                                if (parsed.from?.value?.[0]?.address) {
                                    senderEmail = parsed.from.value[0].address;
                                } else if (parsed.from?.text) {
                                    // Пытаемся извлечь email из текста
                                    const emailMatch = parsed.from.text.match(/[\w.-]+@[\w.-]+\.\w+/);
                                    if (emailMatch) senderEmail = emailMatch[0];
                                }

                                if (parsed.to?.value?.[0]?.address) {
                                    recipientEmail = parsed.to.value[0].address;
                                } else if (parsed.to?.text) {
                                    const emailMatch = parsed.to.text.match(/[\w.-]+@[\w.-]+\.\w+/);
                                    if (emailMatch) recipientEmail = emailMatch[0];
                                }

                                // Обрабатываем поле In-Reply-To
                                let inReplyTo = '';
                                if (parsed.inReplyTo) {
                                    if (Array.isArray(parsed.inReplyTo)) {
                                        inReplyTo = parsed.inReplyTo[0] || ''; // Берем первый элемент, если это массив
                                    } else {
                                        inReplyTo = parsed.inReplyTo;
                                    }
                                }

                                // Обрабатываем references как массив и добавляем inReplyTo
                                let referencesList = [];

                                // Добавляем inReplyTo первым, если он есть
                                if (inReplyTo) {
                                    referencesList.push(inReplyTo);
                                }

                                // Добавляем существующие references
                                if (parsed.references) {
                                    if (Array.isArray(parsed.references)) {
                                        // Добавляем только те, которых еще нет в списке
                                        for (const ref of parsed.references) {
                                            if (!referencesList.includes(ref)) {
                                                referencesList.push(ref);
                                            }
                                        }
                                    } else if (typeof parsed.references === 'string') {
                                        // Разбиваем строку по пробелам или запятым
                                        const refs = parsed.references.split(/[\s,]+/).filter(ref => ref.trim() !== '');
                                        for (const ref of refs) {
                                            if (!referencesList.includes(ref)) {
                                                referencesList.push(ref);
                                            }
                                        }
                                    }
                                }

                                results.push({
                                    id: idCounter++,
                                    sender: senderEmail,
                                    sender_full: parsed.from?.text || '',
                                    recipient: recipientEmail,
                                    recipient_full: parsed.to?.text || '',
                                    message_id: parsed.messageId || '',
                                    references: referencesList, // References как массив, включая in_reply_to
                                    date: parsed.date ? parsed.date.toString() : new Date().toString(),
                                    folder: 'Рассылки|К обработке с ИИ',
                                    uid: uid,
                                    subject: fixedSubject,
                                    textPlain: fixedText,
                                    // textHtml: fixedHtml,
                                    body: fixedText || '',
                                    encoding_fixed: true
                                });

                                console.log(`Обработано ${processed}/${total} писем`);

                            } catch (e) {
                                console.error(`Ошибка обработки письма UID ${uid}:`, e.message);
                                // Продолжаем обработку других писем, не завершаем полностью
                            }
                        });
                    });

                    f.once('error', err => {
                        console.error('Ошибка fetch:', err);
                        reject(err);
                    });

                    f.once('end', function () {
                        console.log(`Всего обработано писем: ${results.length} (ограничение: 100)`);
                        imap.end();
                        resolve(results);
                    });
                });
            });
        });

        imap.once('error', err => {
            console.error('IMAP ошибка подключения:', err);
            reject(err);
        });

        imap.once('end', function () {
            console.log('Соединение закрыто');
        });

        imap.connect();
    });
}

